@layer hj.components {
  /* Customise: --hj-toggle-height · --hj-toggle-radius */
  .hj-toggle {
    --_h: var(--hj-toggle-height, calc(40px * var(--hj-density-size)));
    position: relative;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    gap: calc(6px * var(--hj-density));
    height: var(--_h);
    min-width: var(--_h);
    padding: 0 calc(14px * var(--hj-density));
    border: 0;
    border-radius: var(--hj-toggle-radius, var(--hj-radius-pill));
    background: transparent;
    color: var(--hj-fg-dim);
    font: 600 13.5px / 1 var(--hj-font-sans);
    white-space: nowrap;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      box-shadow var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-toggle[data-size='sm'] {
    --_h: var(--hj-toggle-height, calc(32px * var(--hj-density-size)));
    padding: 0 calc(10px * var(--hj-density));
    font-size: 12.5px;
  }
  .hj-toggle[data-icon-only] {
    width: var(--_h);
    padding: 0;
  }
  /* 44px hit area for the small size */
  .hj-toggle[data-size='sm']::before {
    content: '';
    position: absolute;
    inset: calc((var(--_h) - var(--hj-touch)) / 2) 0;
  }
  .hj-toggle .hj-icon {
    font-size: 18px;
  }
  .hj-toggle[data-size='sm'] .hj-icon {
    font-size: 16px;
  }
  .hj-toggle[data-variant='outline'] {
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
  }
  .hj-toggle:hover:not([data-disabled]):not([data-pressed]) {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg);
  }
  .hj-toggle[data-variant='outline']:hover:not([data-disabled]):not([data-pressed]) {
    background: color-mix(in srgb, var(--hj-fg) 4%, var(--hj-surface));
  }
  .hj-toggle[data-pressed] {
    background: var(--hj-accent-soft);
    color: var(--hj-accent);
    box-shadow: inset 0 0 0 1px transparent;
  }
  .hj-toggle:active:not([data-disabled]) {
    transform: scale(var(--hj-press));
    transition-duration: var(--hj-dur-fast), var(--hj-dur-fast), var(--hj-dur-fast), 70ms;
  }
  .hj-toggle[data-disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }
  /* inside a ToggleGroup: flush, the group draws the frame */
  .hj-toggle[data-variant='grouped'] {
    --_h: calc(var(--hj-toggle-height, calc(40px * var(--hj-density-size))) - 8px);
  }
  .hj-toggle[data-variant='grouped'][data-size='sm'] {
    --_h: calc(var(--hj-toggle-height, calc(32px * var(--hj-density-size))) - 6px);
  }
}

'use client';
import { Toggle as BaseToggle } from '@base-ui/react/toggle';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

/** Provided by ToggleGroup: its size. Toggles inside take it and sit flush (null = not grouped). */
export type ToggleGroupContextValue = 'sm' | 'md' | null;
export const ToggleGroupContext: React.Context<ToggleGroupContextValue> =
  React.createContext<ToggleGroupContextValue>(null);

export interface ToggleOwnProps {
  /** md = 40, sm = 32. Inside a ToggleGroup it takes the group's size. */
  size?: 'sm' | 'md';
  /** quiet = no fill until pressed; outline = surface with a hairline. Ignored inside a group. */
  variant?: 'quiet' | 'outline';
  /** Square, for a lone icon. Give it an aria-label. */
  iconOnly?: boolean;
}
export interface ToggleProps extends ToggleOwnProps, BaseToggle.Props {}

/**
 * A button that stays pressed: Bold, Shuffle, Mute. Pressed is accent-soft with an accent glyph.
 * Not for settings (use Switch) or for one-of-many (use SegmentedControl).
 */
export function Toggle(props: ToggleProps): React.ReactElement {
  const config = useHanjiConfig();
  const group = React.useContext(ToggleGroupContext);
  const {
    size,
    variant = 'quiet',
    iconOnly = false,
    className,
    ...rest
  } = withDefaults(config, 'Toggle', props);
  return (
    <BaseToggle
      {...rest}
      data-size={size ?? group ?? 'md'}
      data-variant={group ? 'grouped' : variant}
      data-icon-only={flag(iconOnly)}
      className={cls(config, 'Toggle', 'hj-toggle', className)}
    />
  );
}
